import {useState} from 'react';import {createRoot} from 'react-dom/client';
import {SelectedWorkloadCapacity} from '../../components/workload-capacity-planning';
import {decisionStore,useDecisionStorage,switchDecisionDataset} from '../../components/decision-store';
import {planAlternativesField,readPlanAlternatives} from '../../lib/home-plan-alternatives';
import {PlanAlternativeCard} from '../../components/plan-alternative-card';
import {solutionPlanView} from '../../lib/home-solution-model-view';
const goals=[{id:'capacity-goal',statement:'Review synthetic ticket workload'},{id:'other-goal',statement:'Review another synthetic workload'}];
function Harness(){const state=useDecisionStorage(),[route,setRoute]=useState(true),[epoch,setEpoch]=useState(0);const goal=state.data.goals.goals.find(g=>g.id===state.data.goals.activeId)!,catalog=readPlanAlternatives(state.data.workspaces[goal.id]?.fields[planAlternativesField],{goalId:goal.id,goal:goal.statement});
 return <main className="mx-auto max-w-6xl"><nav className="flex flex-wrap gap-2" aria-label="Synthetic save controls"><button className="min-h-11 rounded border p-2" onClick={()=>setRoute(!route)}>Switch synthetic route</button><button className="min-h-11 rounded border p-2" onClick={()=>{setEpoch(epoch+1);}}>Reload saved view</button><button className="min-h-11 rounded border p-2" onClick={()=>decisionStore.saveGoals({...state.data.goals,activeId:goal.id===goals[0].id?goals[1].id:goals[0].id})}>Switch synthetic goal</button><button className="min-h-11 rounded border p-2" onClick={()=>{switchDecisionDataset(decisionStore.getDatasetToken()==='legacy-v1:0'?'other:1':'legacy-v1:0');setEpoch(epoch+1);}}>Switch synthetic dataset</button><button className="min-h-11 rounded border p-2" onClick={()=>decisionStore.setField(goal.id,'unrelated-store-race',crypto.randomUUID())}>Change browser-store revision</button></nav>{route?<SelectedWorkloadCapacity key={epoch}/>:<h1>Synthetic Planning Overview</h1>}<section aria-label="Synthetic attached workload history">{catalog?.attachments.map(a=><PlanAlternativeCard key={a.id} plan={catalog.plans.find(p=>p.id===a.planId)!} catalog={catalog} snapshot compact/>)}</section><output data-testid="saved" hidden>{JSON.stringify(state.data)}</output><output data-testid="catalog" hidden>{JSON.stringify(catalog)}</output><output data-testid="model-view" hidden>{JSON.stringify(catalog?.plans.map(solutionPlanView)??[])}</output></main>;
}
decisionStore.initialize(localStorage);if(!decisionStore.getSnapshot().data.goals.goals.length)decisionStore.saveGoals({version:1,activeId:goals[0].id,goals});createRoot(document.getElementById('root')!).render(<Harness/>);
